int stream_group_reset_offsets_if_generation(StreamStore*s,const char*n,uint32_t l,const char*g,uint32_t gl,uint64_t expected,StreamOffsetResetStrategy strategy,uint64_t absolute,int64_t delta,int force,uint64_t*old,uint64_t*next,uint32_t cap,uint32_t*out_count){if(!s||!g||!gl||gl>STREAM_GROUP_MAX||strategy>STREAM_OFFSET_RESET_RELATIVE)return-1;if(out_count)*out_count=0;pthread_mutex_lock(&s->mu);if(s->failed||compact_maybe_locked(s)){pthread_mutex_unlock(&s->mu);return-1;}StreamTopic*t=topic(s,n,l);StreamGroup*x=t?group(s,t,g,gl,0):NULL;if(!t||!x){pthread_mutex_unlock(&s->mu);return 3;}if((old||next)&&cap<t->partitions){pthread_mutex_unlock(&s->mu);return-1;}group_reap_locked(x,mono_ms());if(x->generation!=expected){pthread_mutex_unlock(&s->mu);return 1;}if(x->member_count&&!force){pthread_mutex_unlock(&s->mu);return 4;}uint64_t targets[STREAM_PARTITIONS_MAX];for(uint32_t p=0;p<t->partitions;p++){uint64_t value=0,current=x->offsets[p];if(strategy==STREAM_OFFSET_RESET_EARLIEST)value=t->parts[p].base;else if(strategy==STREAM_OFFSET_RESET_LATEST)value=t->parts[p].next;else if(strategy==STREAM_OFFSET_RESET_ABSOLUTE)value=absolute;else if(delta<0){uint64_t amount=(uint64_t)(-(delta+1))+1u;if(amount>current){pthread_mutex_unlock(&s->mu);return 2;}value=current-amount;}else{uint64_t amount=(uint64_t)delta;if(amount>UINT64_MAX-current){pthread_mutex_unlock(&s->mu);return 2;}value=current+amount;}if(value<t->parts[p].base||value>t->parts[p].next){pthread_mutex_unlock(&s->mu);return 2;}targets[p]=value;if(old)old[p]=current;if(next)next[p]=value;}size_t record=16u+l+gl;if(record>UINT32_MAX/t->partitions){pthread_mutex_unlock(&s->mu);return-1;}unsigned char*b=malloc(record*t->partitions);if(!b){pthread_mutex_unlock(&s->mu);return-1;}size_t pos=0;for(uint32_t p=0;p<t->partitions;p++){u16(b+pos,l);memcpy(b+pos+2,n,l);u16(b+pos+2+l,gl);memcpy(b+pos+4+l,g,gl);u32(b+pos+4+l+gl,p);u64(b+pos+8+l+gl,targets[p]);pos+=record;}int rc=0;pos=0;for(uint32_t p=0;p<t->partitions&&!rc;p++){rc=log_record(s,S_COMMIT,b+pos,(uint32_t)record);pos+=record;}free(b);if(!rc){for(uint32_t p=0;p<t->partitions;p++)x->offsets[p]=targets[p];rc=stream_wait_durable_locked(s,s->wal_seq);if(!rc&&out_count)*out_count=t->partitions;}pthread_mutex_unlock(&s->mu);return rc;}
int stream_group_join(StreamStore*s,const char*n,uint32_t l,const char*g,uint32_t gl,uint64_t owner,uint32_t lease,uint32_t**out,uint32_t*count,uint64_t*out_generation){if(!s||!g||!gl||gl>STREAM_GROUP_MAX||!owner||!out||!count||!lease||lease>60000)return-1;*out=NULL;*count=0;if(out_generation)*out_generation=0;pthread_mutex_lock(&s->mu);StreamTopic*t=topic(s,n,l);if(!t){pthread_mutex_unlock(&s->mu);return-1;}StreamGroup*x=group(s,t,g,gl,1);if(!x){pthread_mutex_unlock(&s->mu);return-1;}uint64_t now=mono_ms();group_reap_locked(x,now);StreamMember*m=x->members;while(m&&m->owner!=owner)m=m->next;if(!m){if(x->member_count>=STREAM_GROUP_MEMBERS_MAX){pthread_mutex_unlock(&s->mu);return-1;}m=calloc(1,sizeof*m);if(!m){pthread_mutex_unlock(&s->mu);return-1;}m->owner=owner;m->next=x->members;x->members=m;x->member_count++;x->generation++;}m->deadline_ms=now+lease;uint64_t owners[STREAM_GROUP_MEMBERS_MAX];uint32_t members=group_owners_locked(x,now,owners),assigned=0;for(uint32_t p=0;p<t->partitions;p++)if(owners[p%members]==owner)assigned++;uint32_t*parts=calloc(assigned?assigned:1,sizeof*parts);if(!parts){pthread_mutex_unlock(&s->mu);return-1;}uint32_t at=0;for(uint32_t p=0;p<t->partitions;p++)if(owners[p%members]==owner)parts[at++]=p;pthread_mutex_unlock(&s->mu);*out=parts;*count=assigned;if(out_generation)*out_generation=x->generation;return 0;}
int stream_group_leave_member(StreamStore*s,const char*n,uint32_t l,const char*g,uint32_t gl,uint64_t owner){if(!s||!g||!gl||gl>STREAM_GROUP_MAX||!owner)return-1;pthread_mutex_lock(&s->mu);StreamTopic*t=topic(s,n,l);StreamGroup*x=t?group(s,t,g,gl,0):NULL;int removed=0;if(x)for(StreamMember**link=&x->members;*link;){StreamMember*m=*link;if(m->owner!=owner){link=&m->next;continue;}*link=m->next;free(m);if(x->member_count)x->member_count--;x->generation++;removed=1;break;}pthread_mutex_unlock(&s->mu);return removed?0:-1;}
void stream_group_leave_owner(StreamStore*s,uint64_t owner){if(!s||!owner)return;pthread_mutex_lock(&s->mu);for(StreamTopic*t=s->topics;t;t=t->next)for(StreamGroup*g=t->groups;g;g=g->next)for(StreamMember**link=&g->members;*link;){StreamMember*m=*link;if(m->owner!=owner){link=&m->next;continue;}*link=m->next;free(m);if(g->member_count)g->member_count--;g->generation++;}pthread_mutex_unlock(&s->mu);}
void stream_reap(StreamStore*s){if(!s)return;pthread_mutex_lock(&s->mu);uint64_t now=mono_ms();for(StreamTopic*t=s->topics;t;t=t->next)for(StreamGroup*g=t->groups;g;g=g->next)group_reap_locked(g,now);pthread_mutex_unlock(&s->mu);}
int stream_group_member_assigned(StreamStore*s,const char*n,uint32_t l,const char*g,uint32_t gl,uint64_t owner,uint32_t p,uint64_t*out_generation){if(!s||!g||!gl||gl>STREAM_GROUP_MAX||!owner)return-1;pthread_mutex_lock(&s->mu);StreamTopic*t=topic(s,n,l);StreamGroup*x=t?group(s,t,g,gl,0):NULL;if(!t||!x||p>=t->partitions){pthread_mutex_unlock(&s->mu);return 0;}uint64_t now=mono_ms();int assigned=member_assigned_locked(x,owner,p,now);if(out_generation)*out_generation=x->generation;pthread_mutex_unlock(&s->mu);return assigned?1:0;}
int stream_commit_for_owner(StreamStore*s,const char*n,uint32_t l,const char*g,uint32_t gl,uint32_t p,uint64_t off,uint64_t owner){if(!s||!g||!gl||gl>STREAM_GROUP_MAX||!owner)return-1;pthread_mutex_lock(&s->mu);if(s->failed||compact_maybe_locked(s)){pthread_mutex_unlock(&s->mu);return-1;}StreamTopic*t=topic(s,n,l);StreamGroup*x=t?group(s,t,g,gl,0):NULL;if(!t||!x||p>=t->partitions||!member_assigned_locked(x,owner,p,mono_ms())){pthread_mutex_unlock(&s->mu);return-1;}unsigned char*b=malloc(16+l+gl);if(!b){pthread_mutex_unlock(&s->mu);return-1;}u16(b,l);memcpy(b+2,n,l);u16(b+2+l,gl);memcpy(b+4+l,g,gl);u32(b+4+l+gl,p);u64(b+8+l+gl,off);int rc=log_record(s,S_COMMIT,b,16+l+gl);free(b);if(!rc){x->offsets[p]=off;rc=stream_wait_durable_locked(s,s->wal_seq);}pthread_mutex_unlock(&s->mu);return rc;}
int stream_commit_for_owner_if_generation(StreamStore*s,const char*n,uint32_t l,const char*g,uint32_t gl,uint32_t p,uint64_t off,uint64_t owner,uint64_t expected){if(!s||!g||!gl||gl>STREAM_GROUP_MAX||!owner)return-1;pthread_mutex_lock(&s->mu);if(s->failed||compact_maybe_locked(s)){pthread_mutex_unlock(&s->mu);return-1;}StreamTopic*t=topic(s,n,l);StreamGroup*x=t?group(s,t,g,gl,0):NULL;if(!t||!x||p>=t->partitions){pthread_mutex_unlock(&s->mu);return 3;}uint64_t now=mono_ms();if(!member_assigned_locked(x,owner,p,now)){pthread_mutex_unlock(&s->mu);return 3;}if(x->generation!=expected){pthread_mutex_unlock(&s->mu);return 1;}if(off<t->parts[p].base||off>t->parts[p].next){pthread_mutex_unlock(&s->mu);return 2;}unsigned char*b=malloc(16+l+gl);if(!b){pthread_mutex_unlock(&s->mu);return-1;}u16(b,l);memcpy(b+2,n,l);u16(b+2+l,gl);memcpy(b+4+l,g,gl);u32(b+4+l+gl,p);u64(b+8+l+gl,off);int rc=log_record(s,S_COMMIT,b,16+l+gl);free(b);if(!rc){x->offsets[p]=off;rc=stream_wait_durable_locked(s,s->wal_seq);}pthread_mutex_unlock(&s->mu);return rc;}
/* Batch offset commit: one lock hold, one durability wait for the whole
 * batch. Entries apply in order, so a later entry for the same partition
 * overwrites an earlier one, matching sequential single commits. */
int stream_commit_batch_for_owner(StreamStore*s,const char*n,uint32_t l,const char*g,uint32_t gl,uint64_t owner,const StreamCommitInput*in,uint32_t count){if(!s||!g||!gl||gl>STREAM_GROUP_MAX||!count||!in)return-1;pthread_mutex_lock(&s->mu);if(s->failed||compact_maybe_locked(s)){pthread_mutex_unlock(&s->mu);return-1;}StreamTopic*t=topic(s,n,l);if(!t){pthread_mutex_unlock(&s->mu);return-1;}StreamGroup*x=group(s,t,g,gl,owner==0?1:0);if(!x){pthread_mutex_unlock(&s->mu);return-1;}uint64_t now=mono_ms();for(uint32_t i=0;i<count;i++){if(in[i].partition>=t->partitions){pthread_mutex_unlock(&s->mu);return-1;}if(owner&&!member_assigned_locked(x,owner,in[i].partition,now)){pthread_mutex_unlock(&s->mu);return-1;}}unsigned char*b=malloc((16u+l+gl)*count);if(!b){pthread_mutex_unlock(&s->mu);return-1;}size_t pos=0;for(uint32_t i=0;i<count;i++){u16(b+pos,l);memcpy(b+pos+2,n,l);u16(b+pos+2+l,gl);memcpy(b+pos+4+l,g,gl);u32(b+pos+4+l+gl,in[i].partition);u64(b+pos+8+l+gl,in[i].offset);pos+=16u+l+gl;}int rc=0;pos=0;for(uint32_t i=0;i<count&&!rc;i++){rc=log_record(s,S_COMMIT,b+pos,16u+l+gl);pos+=16u+l+gl;}free(b);if(!rc){for(uint32_t i=0;i<count;i++)x->offsets[in[i].partition]=in[i].offset;rc=stream_wait_durable_locked(s,s->wal_seq);}pthread_mutex_unlock(&s->mu);return rc;}
int stream_group_offset(StreamStore*s,const char*n,uint32_t l,const char*g,uint32_t gl,uint32_t p,uint64_t*out){if(!s||!out)return-1;pthread_mutex_lock(&s->mu);StreamTopic*t=topic(s,n,l);StreamGroup*x=t?group(s,t,g,gl,0):NULL;if(!x||p>=t->partitions){pthread_mutex_unlock(&s->mu);return 0;}*out=x->offsets[p];pthread_mutex_unlock(&s->mu);return 1;}
int stream_group_lag(StreamStore*s,const char*n,uint32_t l,const char*g,uint32_t gl,uint32_t p,uint64_t*out){if(!s||!out)return-1;pthread_mutex_lock(&s->mu);StreamTopic*t=topic(s,n,l);StreamGroup*x=t?group(s,t,g,gl,0):NULL;if(!x||p>=t->partitions){pthread_mutex_unlock(&s->mu);return 0;}uint64_t end=t->parts[p].next,offset=x->offsets[p];*out=end>offset?end-offset:0;pthread_mutex_unlock(&s->mu);return 1;}
uint64_t stream_topic_count(StreamStore*s){uint64_t n=0;pthread_mutex_lock(&s->mu);for(StreamTopic*t=s->topics;t;t=t->next)n++;pthread_mutex_unlock(&s->mu);return n;}
void stream_foreach_stats(StreamStore*s,StreamTopicStatsFn fn,void*ud){if(!s||!fn)return;pthread_mutex_lock(&s->mu);for(StreamTopic*t=s->topics;t;t=t->next)fn(t->name,t->len,t->partitions,t->bytes,t->records,ud);pthread_mutex_unlock(&s->mu);}uint64_t stream_partition_count(StreamStore*s){uint64_t n=0;pthread_mutex_lock(&s->mu);for(StreamTopic*t=s->topics;t;t=t->next)n+=t->partitions;pthread_mutex_unlock(&s->mu);return n;}uint64_t stream_retention_bytes(StreamStore*s){uint64_t n=0;pthread_mutex_lock(&s->mu);for(StreamTopic*t=s->topics;t;t=t->next)n+=t->bytes;pthread_mutex_unlock(&s->mu);return n;}void stream_group_foreach_stats(StreamStore*s,StreamGroupStatsFn fn,void*ud){if(!s||!fn)return;pthread_mutex_lock(&s->mu);uint64_t now=mono_ms();for(StreamTopic*t=s->topics;t;t=t->next)for(StreamGroup*g=t->groups;g;g=g->next){group_reap_locked(g,now);fn(t->name,t->len,g->name,g->len,g->generation,g->member_count,ud);}pthread_mutex_unlock(&s->mu);}
int stream_group_member_snapshot(StreamStore*s,const char*n,uint32_t l,const char*g,uint32_t gl,StreamGroupMemberSnapshotFn fn,void*ud,uint64_t*out_generation,uint32_t*out_member_count){if(!s||!g||!gl||gl>STREAM_GROUP_MAX||!fn)return-1;pthread_mutex_lock(&s->mu);StreamTopic*t=topic(s,n,l);StreamGroup*x=t?group(s,t,g,gl,0):NULL;if(!t||!x){pthread_mutex_unlock(&s->mu);return 0;}uint64_t now=mono_ms(),owners[STREAM_GROUP_MEMBERS_MAX];uint32_t count=group_owners_locked(x,now,owners);if(out_generation)*out_generation=x->generation;if(out_member_count)*out_member_count=count;for(uint32_t i=0;i<count;i++){uint32_t assigned=0;uint64_t deadline=0;for(uint32_t p=0;p<t->partitions;p++)if(owners[p%count]==owners[i])assigned++;for(StreamMember*m=x->members;m;m=m->next)if(m->owner==owners[i]){deadline=m->deadline_ms;break;}fn(i,assigned,deadline>now?deadline-now:0,ud);}pthread_mutex_unlock(&s->mu);return 1;}
uint64_t stream_group_count(StreamStore*s){uint64_t n=0;pthread_mutex_lock(&s->mu);for(StreamTopic*t=s->topics;t;t=t->next)for(StreamGroup*g=t->groups;g;g=g->next)n++;pthread_mutex_unlock(&s->mu);return n;}uint64_t stream_group_member_count(StreamStore*s){uint64_t n=0,now=mono_ms();pthread_mutex_lock(&s->mu);for(StreamTopic*t=s->topics;t;t=t->next)for(StreamGroup*g=t->groups;g;g=g->next){group_reap_locked(g,now);n+=g->member_count;}pthread_mutex_unlock(&s->mu);return n;}int stream_persistence_failed(StreamStore*s){pthread_mutex_lock(&s->mu);int n=s->failed;pthread_mutex_unlock(&s->mu);return n;}
int stream_checkpoint_maybe(StreamStore*s){if(!s)return-1;pthread_mutex_lock(&s->mu);if(s->failed||s->fd<0){pthread_mutex_unlock(&s->mu);return-1;}uint64_t before=s->wal_bytes;int rc=compact_maybe_locked(s);int changed=rc?0:s->wal_bytes<before;pthread_mutex_unlock(&s->mu);return rc?-1:changed;}
void stream_debug_recount(StreamStore*s,uint64_t*full_records,uint64_t*full_live,uint64_t*incr_live){if(!s)return;pthread_mutex_lock(&s->mu);uint64_t records=0,live=0;for(StreamTopic*t=s->topics;t;t=t->next){live+=22u+t->len;for(uint32_t p=0;p<t->partitions;p++)for(StreamRecord*r=t->parts[p].head;r;r=r->next){records++;live+=record_live(t,r);}for(StreamGroup*g=t->groups;g;g=g->next)live+=(uint64_t)t->partitions*(25u+t->len+g->len);}if(full_records)*full_records=records;if(full_live)*full_live=live;if(incr_live)*incr_live=s->live_bytes;pthread_mutex_unlock(&s->mu);}
